	for rows.Next() {
		var id string
		if err := rows.Scan(&id); err != nil {
			rows.Close()
			return
		}
		ids = append(ids, id)
	}
	rows.Close()

	for _, id := range ids {
		tx, err := s.db.Begin()
		if err != nil {
			return
		}
		row, err := readRow(tx, id)
		if err != nil {
