	st := newTestStore(t)

	outcome, err := st.Acquire("res", "a", 10)
	if err != nil {
		t.Fatalf("acquire: %v", err)
	}
	if outcome.Status != StatusAcquired {
		t.Fatalf("status = %q, want ACQUIRED", outcome.Status)
